h\":\"/ja/library/bg/2/20/\"},{\"display_name\":\"한국어 (Korean)\",\"language_code\":\"ko\",\"enabled\":true,\"url_path\":\"/ko/library/bg/2/20/\"},{\"display_name\":\"Lietuvių kalba (Lithuanian)\",\"language_code\":\"lt\",\"enabled\":true,\"url_path\":\"/lt/library/bg/2/20/\"},{\"display_name\":\"Nederlands (Dutch)\",\"language_code\":\"nl\",\"enabled\":true,\"url_path\":\"/nl/library/bg/2/20/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/2/20/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/2/20/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/2/20/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/2/20/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/2/20/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/2/20/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/2/\",\"title\":\"Chapter Two: Contents of the Gītā Summarized\"}],\"url_path\":\"/en/library/bg/2/20/\",\"bb\":535,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/2/19/\",\"title\":\"TEXT 19\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/2/21/\",\"title\":\"TEXT 21\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":589,\"bb\":567944,\"url_path\":\"/en/library/bg/2/20/devanagari/\",\"body_final\":\"न जायते म्रियते वा कदाचि-
न्नायं भूत्वा भविता वा न भूयः ।
अजो नित्यः शाश्वतोऽयं पुराणो
न हन्यते हन्यमाने शरीरे ॥ २० ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":590,\"bb\":536,\"url_path\":\"/en/library/bg/2/20/b536/\",\"body_value\":\"na jāyate mriyate vā kadācin
nāyaṁ bhūtvā bhavitā vā na bhūyaḥ
ajo nityaḥ śāśvato ’yaṁ purāṇo
na hanyate hanyamāne śarīre\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":591,\"bb\":537,\"url_path\":\"/en/library/bg/2/20/b537/\",\"shadow_value\":\"na – never; jāyate – takes birth; mriyate – dies; vā – either; kadācit – at any time (past, present or future); na – never; ayam – this; bhūtvā – having come into being; bhavitā – will come to be; vā – or; na – not; bhūyaḥ – or is again coming to be; ajaḥ – unborn; nityaḥ – eternal; śāśvataḥ – permanent; ayam – this; purāṇaḥ – the oldest; na – never; hanyate – is killed; hanyamāne – being killed; śarīre – the body.\",\"word_for_word_value\":[{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"jāyate\",\"translation\":\"takes birth\"},{\"word\":\"mriyate\",\"translation\":\"dies\"},{\"word\":\"vā\",\"translation\":\"either\"},{\"word\":\"kadācit\",\"translation\":\"at any time (past, present or future)\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"ayam\",\"translation\":\"this\"},{\"word\":\"bhūtvā\",\"translation\":\"having come into being\"},{\"word\":\"bhavitā\",\"translation\":\"will come to be\"},{\"word\":\"vā\",\"translation\":\"or\"},{\"word\":\"na\",\"translation\":\"not\"},{\"word\":\"bhūyaḥ\",\"translation\":\"or is again coming to be\"},{\"word\":\"ajaḥ\",\"translation\":\"unborn\"},{\"word\":\"nityaḥ\",\"translation\":\"eternal\"},{\"word\":\"śāśvataḥ\",\"translation\":\"permanent\"},{\"word\":\"ayam\",\"translation\":\"this\"},{\"word\":\"purāṇaḥ\",\"translation\":\"the oldest\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"hanyate\",\"translation\":\"is killed\"},{\"word\":\"hanyamāne\",\"translation\":\"being killed\"},{\"word\":\"śarīre\",\"translation\":\"the body\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":592,\"bb\":538,\"url_path\":\"/en/library/bg/2/20/b538/\",\"body_value\":\"For the soul there is neither birth nor death at any time. He has not come into being, does not come into being, and will not come into being. He is unborn, eternal, ever-existing and primeval. He is not slain when the body is slain.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":593,\"bb\":539,\"url_path\":\"/en/library/bg/2/20/b539/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":594,\"bb\":540,\"url_path\":\"/en/library/bg/2/20/b540/\",\"body_value\":\"In the Kaṭha Upaniṣad (1.2.18) we also find a similar passage, which reads:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":595,\"bb\":541,\"url_path\":\"/en/library/bg/2/20/b541/\",\"body_value\":\"na jāyate mriyate vā vipaścin
nāyaṁ kutaścin na babhūva kaścit
ajo nityaḥ śāśvato ’yaṁ purāṇo
na hanyate hanyamāne śarīre\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":596,\"bb\":542,\"url_path\":\"/en/library/bg/2/20/b542/\",\"body_value\":\"The meaning and purport of this verse is the same as in the Bhagavad-gītā, but here in this verse there is one special word, vipaścit, which means learned or with knowledge.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":597,\"bb\":543,\"url_path\":\"/en/library/bg/2/20/b543/\",\"body_value\":\"$26\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":598,\"bb\":544,\"url_path\":\"/en/library/bg/2/20/b544/\",\"body_value\":\"There are two kinds of souls – namely the minute particle soul (aṇu-ātmā) and the Supersoul (vibhu-ātmā). This is also confirmed in the Kaṭha Upaniṣad (1.2.20) in this way:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":599,\"bb\":545,\"url_path\":\"/en/library/bg/2/20/b545/\",\"body_value\":\"aṇor aṇīyān mahato mahīyān
ātmāsya jantor nihito guhāyām
tam akratuḥ paśyati vīta-śoko
dhātuḥ prasādān mahimānam ātmanaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":600,\"bb\":546,\"url_path\":\"/en/library/bg/2/20/b546/\",\"body_value\":\"“Both the Supersoul [Paramātmā] and the atomic soul [ jīvātmā] are situated on the same tree of the body within the same heart of the living being, and only one who has become free from all material desires as well as lamentations can, by the grace of the Supreme, understand the glories of the soul.” Kṛṣṇa is the fountainhead of the Supersoul also, as it will be disclosed in the following chapters, and Arjuna is the atomic soul, forgetful of his real nature; therefore he requires to be enlightened by Kṛṣṇa, or by His bona fide representative (the spiritual master).\"}]}],\"short_title\":\"Bg. 2.20\",\"medium_title\":\"Bhagavad-gītā As It Is 2.20\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L27\",\"$L28\",\"$L29\"]}]\n"])self.__next_f.push([1,"2b:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n31:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n27:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"chi